import {renderCompensationEditor,calculationHTML,credit} from './compensation.js';
import {escapeHtml as esc} from './message-format.js';
import {localInstant,localAt,resultValue} from './oncall-planning.js';
export const money=(minor,digits=2)=>{const n=BigInt(minor),sign=n<0n?'-':'',s=(n<0n?-n:n).toString().padStart(Number(digits)+1,'0');return sign+(Number(digits)?s.slice(0,-Number(digits))+'.'+s.slice(-Number(digits)):s);};
export function parseMoney(value,digits=2){const s=String(value).trim(),d=Number(digits);if(!new RegExp(`^-?\\d+(?:\\.\\d{1,${d||1}})?$`).test(s)||(d===0&&s.includes('.')))throw Error(`Use an amount with at most ${d} decimal places.`);const [a,b='']=s.replace('-','').split('.');return BigInt(a+b.padEnd(d,'0'))*(s.startsWith('-')?-1n:1n);}
export const duration=r=>Object.hasOwn(r.kind,'adjustment')?'Adjustment':`${(Number((r.endAt-r.startAt)/1_000_000_000n-BigInt(r.breakMinutes)*60n)/3600).toFixed(2)} h`;
const key=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
const kind=r=>Object.keys(r.kind)[0],state=r=>Object.keys(r.state)[0],json=v=>JSON.stringify(v,(_,v)=>typeof v==='bigint'?String(v):v);
const fmt=(ns,zone='UTC')=>new Date(Number(ns/1_000_000n)).toLocaleString('en-GB',{timeZone:zone,dateStyle:'medium',timeStyle:'short'});
const field=(id,label,value='',attrs='')=>`<label>${esc(label)}<input name="${id}" value="${esc(value)}" ${attrs}></label>`;
const status='<p data-rp-status role="status" aria-live="polite"></p>';
const heading=(title,sub,action='')=>`<div class="page-heading"><div><span class="eyebrow">ON-CALL / REPORTING · ALPHA</span><h2>${esc(title)}</h2><p class="lead">${esc(sub)}</p></div>${action}</div>`;
export function createReporting({root,api,session,getMe}){
 let generation=0,timer,context='',projects=[],periods=[],currentId='';
 const token=()=>session.load(),identity=()=>getMe()?json([getMe().id,getMe().role,getMe().reporting]):'';
 const active=g=>g===generation&&context===identity();
 const $=s=>root.querySelector(s),notice=t=>{if($('[data-rp-status]'))$('[data-rp-status]').textContent=t;};
 function clear(){generation++;clearTimeout(timer);context='';root.replaceChildren();projects=[];periods=[];}
 async function action(button,work,done){const g=generation;if(button.disabled)return;button.disabled=true;notice('Saving…');try{const response=await work();if(typeof response?.err==="string")throw Error(response.err);const r=resultValue(response);if(active(g))await(done?done(r):show(currentId));}catch(e){if(active(g))notice(e.message||'Connection interrupted. Refresh to check whether the change was saved.');}finally{if(active(g)&&button.isConnected)button.disabled=false;}}
 function form(selector,work,done){$(selector).onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{action(e.submitter,()=>work(f),done);}catch(e){notice(e.message);}};}
 async function show(id=''){
  const g=++generation;clearTimeout(timer);context=identity();currentId=id;root.innerHTML='<p role="status">Loading service statements…</p>';
  try{
   [projects,periods]=await Promise.all([api().reportingProjects(token()),api().reportingPeriods(token())]);if(!active(g))return;
   if(!id||id.startsWith('project-')){list(id.startsWith('project-')?id.slice(8):'');watch(g,id,null);return;}
   if(id.startsWith('policy-')||id.startsWith('new-')){const p=projects.find(p=>String(p.id)===id.split('-')[1]);if(!p?.capabilities.prepare)throw Error('This project requires compensation access from Hub.');const history=api().reportingCompensationRules?(await api().reportingCompensationRules(token(),p.id))[0]:{revision:0n,rules:[]};if(!active(g))return;if(!history)throw Error('Compensation access expired.');if(id.startsWith('policy-'))renderCompensationEditor({root,p,history,periods,api,token,action,notice,money,parseMoney});else periodEditor(p,history);watch(g,id,null);return;}
   const[v]=await api().reportingPeriod(token(),BigInt(id));if(!active(g))return;if(!v)throw Error('This statement is no longer available to your Hub account.');detail(v);watch(g,id,v);
  }catch(e){if(active(g)){root.innerHTML=heading('A fresh check is needed',e.message||'Check your connection and try again.')+'<button data-retry>Try again</button>'; $('[data-retry]').onclick=()=>show(id);}}
 }
 function watch(g,id,v){
  const baseline=json(v?[v.capabilities,v.records.map(r=>r.id),v.policy!==undefined&&v.policy.length,v.lines.map(l=>l.recordId)]:projects.map(p=>[p.id,p.capabilities]));
  timer=setTimeout(async()=>{if(!active(g))return;try{
   if(v){const[fresh]=await api().reportingPeriod(token(),v.period.id);if(!active(g))return;if(!fresh)throw Error('Access expired or was removed in Hub.');const shape=json([fresh.capabilities,fresh.records.map(r=>r.id),fresh.policy!==undefined&&fresh.policy.length,fresh.lines.map(l=>l.recordId)]);if(shape!==baseline){await show(id);return;}if(fresh.period.revision!==v.period.revision)notice('This statement has changed. Refresh before submitting your changes.');}
   else {const fresh=await api().reportingProjects(token());if(!active(g))return;if(json(fresh.map(p=>[p.id,p.capabilities]))!==baseline){await show(id);return;}}
   watch(g,id,v);
  }catch(e){if(active(g)){clear();root.innerHTML=heading('Access needs a fresh check',e.message);}}},30000);
 }
 function list(projectId=''){
  const rows=periods.filter(p=>!projectId||String(p.projectId)===projectId).sort((a,b)=>Number(b.id-a.id));
  root.innerHTML=heading('Time & compensation','Confirm duty, review work and release the statement for payroll.')+`<div class="rp-stages"><span>01 · Confirm service</span><span>02 · Review & calculate</span><span>03 · Release & export</span></div><div class="rp-projects">${projects.filter(p=>!projectId||String(p.id)===projectId).map(p=>`<section class="card"><div class="section-heading"><h3>${esc(p.name)}</h3>${p.capabilities.prepare&&p.policy.length?`<a class="button sm" href="#/reporting/policy-${p.id}">Compensation rules</a>`:''}</div><p class="kv">${[p.capabilities.review?'Review time':'',p.capabilities.prepare?'Prepare compensation':'',p.capabilities.release?'Release statements':'',p.capabilities.export?'Export approved':''].filter(Boolean).join(' · ')||'Your own service records'}</p>${p.capabilities.prepare?`<a class="button primary" href="#/reporting/${p.policy.length?'new':'policy'}-${p.id}">${p.policy.length?'Prepare a period':'Set up compensation'}</a>`:''}</section>`).join('')}</div><div class="section-heading"><h3>Statements</h3><button data-refresh>Refresh</button></div><div class="card flat rp-table"><table><thead><tr><th>Period</th><th>Project</th><th>Status</th><th>Next step</th></tr></thead><tbody>${rows.map(p=>`<tr><td><a href="#/reporting/${p.id}">${esc(p.title)}</a><span class="rowsub">${esc(fmt(p.startAt,p.timezone))} → ${esc(fmt(p.endAt,p.timezone))}</span></td><td>${esc(projects.find(x=>x.id===p.projectId)?.name||'Project')}</td><td><span class="pill ${p.approvedAt?'ok':''}">${p.approvedAt?'Released':p.adjustmentOf?'Adjustment draft':'In review'}</span></td><td>${p.approvedAt?(p.sourceChanged?'Review source correction':'Ready for payroll'):'Open statement'}</td></tr>`).join('')||'<tr><td colspan="4">No statements available. Your project’s compensation preparer creates the reporting period.</td></tr>'}</tbody></table></div><details class="card"><summary>How reporting works</summary><p>Published shifts become service records that the assigned person must confirm. Incident work is imported as separately recorded time. A reviewer checks the evidence, and another authorized person releases the calculation.</p><p>Payroll permissions are assigned in Hub → Permissions → Desk → Reporting access. A reporting grant does not give access to incidents or customer conversations.</p><p>Hourly readiness and work compensation are additive. Dated company rules support hourly or daily readiness, explicit holiday rates and separate time credits. Taxes, statutory overtime and payroll processing stay with your payroll system. Exports are files for review and import; downloading does not mean payment.</p><p>Records expire on the date shown in each statement. Exported files must be handled under your company’s retention policy.</p></details>${status}`;
  $('[data-refresh]').onclick=()=>show(currentId);
 }
 function periodEditor(p,history){
  const request=key(),zone=history?.rules.filter(r=>!r.withdrawnAt).at(-1)?.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC',now=new Date(),start=new Date(Date.UTC(now.getFullYear(),now.getMonth()-1,1)).toISOString().slice(0,10),end=new Date(Date.UTC(now.getFullYear(),now.getMonth(),1)).toISOString().slice(0,10);
  root.innerHTML=`<a class="back-link" href="#/reporting/project-${p.id}">← ${esc(p.name)}</a>`+heading('Prepare a period','Import service evidence without copying incident conversations or customer data.')+`<form class="card rp-form" id="rpPeriod">${field('title','Statement name',start.slice(0,7),'required maxlength="60"')}<div class="row">${field('start','First day · included',start,'required type="date"')}${field('end','Until · excluded',end,'required type="date"')}</div>${field('zone','Timezone',zone,'required')}<p class="kv">Up to 32 days, beginning within the last year. The rule effective on the first day is copied into this statement. Use whole local days; split the statement if a rule changes during the period. Readiness still needs confirmation; completed work still needs independent review. Maximum 200 records per period.</p><div class="btnrow"><button class="primary">Prepare statement</button><a class="button" href="#/reporting/project-${p.id}">Cancel</a></div>${status}</form>`;
  form('#rpPeriod',f=>api().prepareReportingPeriod(token(),request,{projectId:p.id,title:f.get('title'),startAt:localInstant(f.get('start')+'T00:00',f.get('zone')),endAt:localInstant(f.get('end')+'T00:00',f.get('zone')),timezone:f.get('zone')}),v=>{location.hash=`#/reporting/${v.id}`;});
 }
 function detail(v){
  const p=v.period,c=v.capabilities,released=p.approvedAt>0n,adjustment=p.adjustmentOf>0n,me=getMe().id,policy=v.policy[0],unique=[...new Map(v.records.map(r=>[r.personId,r])).values()],name=projects.find(x=>x.id===p.projectId)?.name||'On-call';
  const canAct=!released&&v.records.some(r=>{const st=state(r),own=r.personId===me,reviewer=(kind(r)==='adjustment'?c.prepare:c.review)&&!own;return own&&kind(r)!=='adjustment'&&!['approved','excluded'].includes(st)||reviewer&&st!=='excluded';});
  const independent=p.createdBy===me||policy?.by===me||v.records.some(r=>state(r)==='approved'&&(r.personId===me||r.confirmedBy===me));
  const calculation=v.calculation?.[0],creditTotal=calculation?.lines.filter(l=>Object.hasOwn(l.unit,'minutes')).reduce((n,l)=>n+l.amount,0n)??0n;
  const totals=new Map();for(const l of v.lines)totals.set(l.currency,(totals.get(l.currency)||0n)+l.amount);
  root.innerHTML=`<a class="back-link" href="#/reporting/project-${p.projectId}">← ${esc(name)}</a>`+heading(p.title,`${fmt(p.startAt,p.timezone)} → ${fmt(p.endAt,p.timezone)} · ${p.timezone}`,`<button data-refresh>Refresh</button>`)+`<div class="rp-summary"><section class="card"><span class="eyebrow">${released?'RELEASED STATEMENT':'NEXT STEP'}</span><strong>${released?esc(p.batchId):v.records.some(r=>['pending','disputed'].includes(state(r)))?'Confirm service':v.records.some(r=>state(r)==='confirmed')?'Review evidence':'Review & release'}</strong><span>${released?'Snapshot fixed · corrections stay linked':`${v.records.filter(r=>['approved','excluded'].includes(state(r))).length} / ${v.records.length} records reviewed`}</span></section><section class="card"><span class="eyebrow">${v.lines.length||calculation?.lines.length?(released?(policy?'RELEASED AMOUNT':'YOUR RELEASED AMOUNT'):'REVIEWED AMOUNT · DRAFT'):'RECORDS'}</span><strong>${v.lines.length?[...totals].map(([cur,n])=>`${esc(cur)} ${money(n,v.lines[0].decimals)}`).join(' · '):calculation?.lines.length?'—':v.records.length}${calculation?.lines.some(l=>Object.hasOwn(l.unit,'minutes'))?`<span class="rowsub">${credit(creditTotal)} time credit</span>`:''}</strong><span>${policy?(released?'Readiness + actual work':'Pending and excluded records are not in this total'):'Only the information permitted by your Hub access'}</span></section><section class="card"><span class="eyebrow">RETENTION</span><strong>${esc(new Date(Number(p.deleteAt/1_000_000n)).toLocaleDateString())}</strong><span>Automatic deletion · includes records and journal</span></section></div>${adjustment?`<p class="rp-callout">Linked correction of <a href="#/reporting/${p.adjustmentOf}">statement #${p.adjustmentOf}</a>. ${esc(p.coverageNote)}</p>`:''}${v.blockers.length?`<aside class="rp-callout" role="status"><strong>${released?'Source correction needs review':'Before release'}</strong><ul>${[...new Set(v.blockers)].map(s=>`<li>${esc(s)}</li>`).join('')}</ul></aside>`:''}<div class="btnrow rp-actions">${!released&&!adjustment&&(c.prepare||c.review)?'<button data-import>Refresh service evidence</button>':''}${!released&&c.release?(independent?'<span class="kv">An independent releaser is needed for this statement.</span>':v.blockers.length?'<button class="primary" disabled title="Resolve the listed blockers first">Release after review</button>':'<button class="primary" data-release>Review release</button>'):''}${released&&c.export?'<button class="primary" data-export>Download payroll CSV</button>':''}${released&&c.prepare&&!adjustment?'<button data-adjust>Create linked correction</button>':''}</div>${status}<div id="rpAction"></div>${calculation?calculationHTML(calculation,money):''}<div class="section-heading"><h3>${adjustment?'Corrections':'Service records'}</h3><span class="kv">Readiness and actual work stay separate</span></div><div class="btnrow rp-record-filter"><button data-filter="attention">Needs attention</button><button data-filter="all">All records</button></div><div class="card flat rp-table"><table><thead><tr><th>Person / service</th><th>When</th><th>Quantity</th><th>Status</th>${v.lines.length&&!calculation?'<th>Amount</th>':''}${canAct?'<th>Review</th>':''}</tr></thead><tbody>${v.records.map(r=>{const st=state(r),own=r.personId===me,line=v.lines.find(l=>l.recordId===r.id),canReview=(kind(r)==='adjustment'?c.prepare:c.review)&&!own;return`<tr data-record-state="${st}"><td><strong>${esc(r.name)}</strong><span class="rowsub">${kind(r)==='readiness'?`Readiness · layer ${Number(r.layer)+1}`:kind(r)==='work'?'Actual work':'Correction'}</span>${r.note?`<span class="rowsub">${esc(r.note)}</span>`:''}</td><td>${esc(fmt(r.startAt,p.timezone))}<span class="rowsub">until ${esc(fmt(r.endAt,p.timezone))}${r.breakMinutes?` · ${r.breakMinutes} min break`:''}</span></td><td>${kind(r)==='adjustment'?esc(calculation?.adjustmentUnits.some(([id,u])=>id===r.id&&Object.hasOwn(u,'minutes'))?credit(r.delta):policy?money(r.delta,policy.decimals):'Correction'):duration(r)}</td><td><span class="pill ${st==='approved'?'ok':''}">${esc(st)}</span>${r.reason?`<span class="rowsub">${esc(r.reason)}</span>`:''}</td>${v.lines.length&&!calculation?`<td>${line?esc(line.currency)+' '+money(line.amount,line.decimals):'—'}</td>`:''}${canAct?`<td><div class="btnrow">${!released&&!['approved','excluded'].includes(st)&&own&&kind(r)!=='adjustment'?`<button class="sm" data-record="${r.id}" data-action="confirm">Confirm</button><button class="sm" data-record="${r.id}" data-action="dispute">Dispute</button>`:''}${!released&&canReview?`${st==='confirmed'&&r.confirmedBy!==me?`<button class="sm" data-record="${r.id}" data-action="approve">Approve</button>`:''}${!['approved','excluded'].includes(st)&&v.departed.includes(r.personId)&&c.review&&kind(r)!=='adjustment'?`<button class="sm" data-record="${r.id}" data-action="attest">Attest service</button>`:''}${st!=='excluded'?`<button class="sm" data-record="${r.id}" data-action="exclude">Exclude</button>`:''}`:''}</div></td>`:''}</tr>`;}).join('')||'<tr><td colspan="6">No service records yet. Refresh evidence after work has been recorded.</td></tr>'}</tbody></table></div><p data-record-empty class="rp-callout" hidden>No records need attention. Choose All records to inspect the reviewed evidence.</p><div id="rpRecordAction"></div>${!released&&c.prepare?`<details class="card" ${unique.some(r=>!v.mappings.find(m=>m.personId===r.personId)?.payrollId)?'open':''}><summary>Payroll identifiers</summary><p class="kv">Company payroll IDs, not bank details. Saved for this statement only.</p>${unique.map(r=>`<form data-mapping="${esc(r.personId)}" class="rp-mapping"><label>${esc(r.name)}<input name="payroll" required maxlength="80" value="${esc(v.mappings.find(m=>m.personId===r.personId)?.payrollId||'')}"></label><button>Save identifier</button></form>`).join('')}</details>`:''}${!released&&c.review&&!adjustment?`<details class="card"><summary>Coverage review</summary><p class="kv">If coverage was missing, explain how service evidence was reconciled. This does not certify unconfirmed service.</p><form id="rpCoverage">${field('note','Review note',p.coverageNote,'required minlength="3" maxlength="240"')}<button>Save coverage review</button></form></details>`:''}${!released&&!adjustment&&getMe().role!=='requester'?`<details class="card"><summary>Add my actual work</summary><p class="kv">Use completed intervals not already imported from an incident. Avoid incident details and personal customer data.</p><form id="rpWork" class="rp-form"><div class="row">${field('start','Start · '+p.timezone,'','type="datetime-local" required')}${field('end','End · '+p.timezone,'','type="datetime-local" required')}${field('breaks','Break · minutes','0','type="number" min="0" required')}</div>${field('note','Payroll-safe explanation','','required minlength="3" maxlength="240"')}<button>Submit my work</button></form></details>`:''}${!released&&adjustment&&c.prepare?`<div id="rpAdjustmentForm"></div>`:''}${policy&&!calculation?`<details class="card"><summary>Calculation snapshot · rule revision ${policy.revision}</summary><p>Readiness per hour: ${esc(policy.readinessRates.map(n=>money(n,policy.decimals)).join(' / ')||'Not included')}. Actual work per hour: ${money(policy.workRate,policy.decimals)} ${esc(policy.currency)}.</p><p>Codes: ${esc(policy.readinessCode)} / ${esc(policy.workCode)}. Cost center: ${esc(policy.costCenter||'None')}. Each line rounds to ${policy.decimals} decimal places; CSV hours show six places.</p></details>`:''}${v.audit.length?`<details class="card"><summary>Review history · ${v.audit.length} events</summary>${v.audit.slice().reverse().map(a=>`<p><strong>${esc(a.action.replaceAll('_',' '))}</strong> · ${esc(fmt(a.at,p.timezone))}<span class="rowsub">${esc(a.by)}${a.reason?' · '+esc(a.reason):''}</span></p>`).join('')}</details>`:''}<p class="kv rp-footnote">Released CSVs are payroll input, not proof of payment. Keep the batch ID when importing to avoid duplicate payments.</p>`;
  $('[data-refresh]').onclick=()=>show(String(p.id));
  function filter(mode){$('[data-record-empty]').hidden=mode!=='attention'||v.records.some(r=>!['approved','excluded'].includes(state(r))); root.querySelectorAll('[data-record-state]').forEach(row=>row.hidden=mode==='attention'&&['approved','excluded'].includes(row.dataset.recordState));root.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('primary',b.dataset.filter===mode);b.setAttribute('aria-pressed',String(b.dataset.filter===mode));});}
  const attention=v.records.filter(r=>!['approved','excluded'].includes(state(r))).length;
  $('[data-filter="attention"]').textContent=`Needs attention · ${attention}`;$('[data-filter="all"]').textContent=`All records · ${v.records.length}`;
  root.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>filter(b.dataset.filter));filter(!released&&attention?'attention':'all');
  if($('[data-import]'))$('[data-import]').onclick=e=>action(e.currentTarget,()=>api().refreshReportingPeriod(token(),p.id,p.revision));
  root.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>{const r=v.records.find(r=>String(r.id)===b.dataset.record),type=b.dataset.action,required=['dispute','exclude','attest'].includes(type);$('#rpRecordAction').innerHTML=`<form class="card rp-form" id="rpDecision"><h3>${esc(type[0].toUpperCase()+type.slice(1))} · ${esc(r.name)}</h3><p>${type==='confirm'?'I confirm I provided this service during the stated interval.':type==='attest'?'Attest documented service for an inactive participant. A different reviewer must then approve this record.':'Review the recorded interval and evidence before continuing.'}</p>${field('reason',required?'Reason / evidence':'Review note · optional','',`maxlength="240" ${required?'required minlength="3"':''}`)}<div class="btnrow"><button class="primary">${esc(type[0].toUpperCase()+type.slice(1))}</button><button type="button" data-cancel>Cancel</button></div></form>`;$('#rpRecordAction').scrollIntoView?.({block:'center'});$('[data-cancel]').onclick=()=>$('#rpRecordAction').replaceChildren();form('#rpDecision',f=>type==='attest'?api().attestDepartedService(token(),p.id,r.id,p.revision,f.get('reason')):['confirm','dispute'].includes(type)?api().confirmReportingRecord(token(),p.id,r.id,p.revision,type==='confirm',f.get('reason')):api().reviewReportingRecord(token(),p.id,r.id,p.revision,type==='approve',f.get('reason')));});
  root.querySelectorAll('[data-mapping]').forEach(f=>f.onsubmit=e=>{e.preventDefault();action(e.submitter,()=>api().setReportingMapping(token(),p.id,p.revision,f.dataset.mapping,new FormData(f).get('payroll')));});
  if($('#rpCoverage'))form('#rpCoverage',f=>api().explainReportingCoverage(token(),p.id,p.revision,f.get('note')));
  if($('#rpWork')){const request=key();form('#rpWork',f=>api().addReportingWork(token(),p.id,p.revision,request,{startAt:localInstant(f.get('start'),p.timezone),endAt:localInstant(f.get('end'),p.timezone),breakMinutes:BigInt(f.get('breaks')),note:f.get('note')}));}
  if($('[data-release]'))$('[data-release]').onclick=()=>{$('#rpAction').innerHTML=`<form id="rpRelease" class="card rp-form"><h3>Release this calculation?</h3><p>This fixes the reviewed records, payroll identifiers and amounts. Changes afterwards require a linked correction. You cannot release your own claims, attestations, rules or a period you prepared.</p><label class="checkline"><input type="checkbox" required> I reviewed the service evidence and payroll calculation.</label><button class="primary">Release statement</button></form>`;form('#rpRelease',()=>api().releaseReportingPeriod(token(),p.id,p.revision));};
  if($('[data-export]'))$('[data-export]').onclick=e=>action(e.currentTarget,()=>api().exportReportingPeriod(token(),p.id),r=>{const url=URL.createObjectURL(new Blob([r.csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=r.filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice(`Downloaded ${r.batchId}. Repeated downloads contain the same statement. Import this batch only once.`);});
  if($('[data-adjust]'))$('[data-adjust]').onclick=()=>{const request=key();$('#rpAction').innerHTML=`<form id="rpAdjustment" class="card rp-form"><h3>Create a linked correction</h3>${field('reason','Why is a correction needed?','','required minlength="3" maxlength="240"')}<button>Create correction draft</button></form>`;form('#rpAdjustment',f=>api().prepareReportingAdjustment(token(),p.id,request,f.get('reason')),r=>{location.hash=`#/reporting/${r.id}`;});};
  if($('#rpAdjustmentForm')){const request=key(),original=periods.find(x=>x.id===p.adjustmentOf);$('#rpAdjustmentForm').innerHTML=`<form id="rpAddCorrection" class="card rp-form"><h3>Add a signed correction</h3><p class="kv">Choose a person from the original released statement. Positive adds compensation; negative deducts from the exported amount. Another compensation preparer reviews each correction.</p><label>Person<select name="person" required>${[...new Map(v.adjustmentPeople.map(x=>[x.id,x])).values()].map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></label>${calculation?'<label>Unit<select name="unit"><option value="money">Money</option><option value="minutes">Time credit · minutes</option></select></label>':''}${field('amount','Signed correction'+(calculation?'':' · '+(policy?.currency||'')),'','required inputmode="decimal"')}${field('reason','Reason','','required minlength="3" maxlength="240"')}<button>Add correction</button>${original?`<a class="button" href="#/reporting/${original.id}">Open original</a>`:''}</form>`;form('#rpAddCorrection',f=>calculation?api().addReportingAdjustmentWithUnit(token(),p.id,p.revision,request,f.get('person'),parseMoney(f.get('amount'),f.get('unit')==='minutes'?0:policy?.decimals??2n),{[f.get('unit')]:null},f.get('reason')):api().addReportingAdjustment(token(),p.id,p.revision,request,f.get('person'),parseMoney(f.get('amount'),policy?.decimals??2n),f.get('reason')));}
 }
 return {show,clear};
}
